/**
 * Navigation configuration — data, not markup.
 *
 * The twenty screens of the game, grouped the way a founder thinks about
 * them: what you operate, where the frontier is, how capital moves, what the
 * world is saying, and the controls that end a quarter.
 *
 * The grouping is load-bearing on a phone, where the five groups *are* the
 * bottom tab bar and a group's items are the sub-tabs under the header. Each
 * group therefore has a primary screen — its first item — and that is where
 * tapping the tab lands.
 *
 * Screen agents do not edit this file. Adding a screen means adding a route
 * folder under `src/app/(game)` and an entry here.
 */

import type { IconName } from '../components/ui/icons';

export type NavGroupId = 'operate' | 'frontier' | 'capital' | 'world' | 'play';

export interface NavItem {
  /** Route path, e.g. `/command-centre`. */
  readonly href: string;
  /** Label in the rail. */
  readonly label: string;
  /** The flat mark drawn everywhere this screen is offered. */
  readonly icon: IconName;
  /**
   * The old two-letter monogram.
   *
   * Kept so nothing that still reads the field breaks, but **nothing renders
   * it any more**: every surface draws `icon` instead.
   *
   * @deprecated Use `icon`.
   */
  readonly glyph: string;
  /** One line describing the screen; used as a tooltip and on the landing page. */
  readonly blurb: string;
}

export interface NavGroup {
  readonly id: NavGroupId;
  readonly label: string;
  /** The mark for the group itself: the phone's bottom tab. */
  readonly icon: IconName;
  /** Two or three words for the tab, where `label` would be too long. */
  readonly short: string;
  readonly items: readonly NavItem[];
}

