/** Every screen, flattened, in rail order. */
export const NAV_ITEMS: readonly NavItem[] = NAV_GROUPS.flatMap((group) => group.items);

/** Routes that render inside the game shell. */
export const GAME_ROUTES: readonly string[] = NAV_ITEMS.map((item) => item.href);

/** The screen a session lands on. */
export const HOME_ROUTE = '/command-centre';

/** True when this pathname is that screen, or a route beneath it. */
function matches(pathname: string, href: string): boolean {
  return pathname === href || pathname.startsWith(`${href}/`);
}

/** Look a screen up by pathname; returns null for the landing and auth pages. */
export function navItemFor(pathname: string): NavItem | null {
  return NAV_ITEMS.find((item) => matches(pathname, item.href)) ?? null;
}

/** The group a pathname belongs to, or null. */
export function navGroupFor(pathname: string): NavGroup | null {
  return NAV_GROUPS.find((group) => group.items.some((item) => matches(pathname, item.href))) ?? null;
}

/**
 * The screen a group's tab lands on: its first item.
 *
 * The phone's bottom bar navigates to groups, not screens, so this is the one
 * place that decides what "Capital" means when you tap it.
 */
export function primaryHrefOf(group: NavGroup): string {
  return group.items[0]?.href ?? HOME_ROUTE;
}

/**
 * The sibling screens shown as sub-tabs under the header on a phone.
 *
 * Empty for a group with a single screen — a strip of one tab is noise — and
 * empty off a game route.
 */
export function navSiblingsFor(pathname: string): readonly NavItem[] {
  const group = navGroupFor(pathname);
  if (group === null || group.items.length < 2) return [];
  return group.items;
}

/** True when the shell chrome (rail + status bar) should render for this path. */
export function isGamePath(pathname: string): boolean {
  return navItemFor(pathname) !== null;
}
